function renderHistory(){const ss=[...data.sessions].sort((a,b)=>b.date.localeCompare(a.date));$('#historyList').innerHTML=ss.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Concept</th><th>Activity</th><th>Result</th><th>Help</th><th>Time</th><th>Marks</th><th>Error / reflection</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${fmtDate(s.date)}</td><td>${esc(concept(s.conceptId)?.name||'Deleted concept')}</td><td>${esc(labelKind(s.kind))}</td><td>${s.result===null?'Not assessed':`${s.result}/4`}<br><small>Confidence ${s.confidence||'—'}/5</small></td><td>${esc(s.assistance)}</td><td>${s.minutes} min</td><td>${s.marks!==''&&s.marks!==null?`${s.marks}/${s.outOf||'?'}`:'—'}</td><td>${esc(s.error||'—')}<br>${esc(s.reflection||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><strong>No sessions logged yet.</strong>Complete a planned task and record performance to build evidence.</div>'}
function renderReports(){const cs=scopedConcepts(),studied=cs.filter(c=>stateOf(c)!=='new').length,secure=cs.filter(c=>stateOf(c)==='secure').length,attempts=data.sessions.filter(s=>s.kind==='retrieval'||s.kind==='practice'),ind=attempts.filter(independent),avg=ind.length?Math.round(ind.reduce((n,s)=>n+Number(s.result),0)/ind.length*25):0;const stats=[['Syllabus coverage',`${cs.length?Math.round(studied/cs.length*100):0}%`,`${studied} of ${cs.length} encountered`],['Evidence-secure',`${cs.length?Math.round(secure/cs.length*100):0}%`,`${secure} concepts meet current security rule`],['Independent attempts',ind.length,`${attempts.length} total retrieval/practice attempts`],['Independent result average',`${avg}%`,'Recent logged performance, not exam prediction']];$('#reportStats').innerHTML=stats.map(s=>`<div class="stat-card"><div class="stat-label">${s[0]}</div><div class="stat-value">${s[1]}</div><div class="stat-foot">${s[2]}</div></div>`).join('');let groups={};cs.forEach(c=>{let key=`${c.subject}|||${c.topic}`;(groups[key] ||= []).push(c)});$('#topicReport').innerHTML=Object.entries(groups).map(([key,a])=>{let [s,t]=key.split('|||'),cover=a.filter(c=>stateOf(c)!=='new').length,m=a.length?Math.round(a.reduce((n,c)=>n+mastery(c),0)/a.length):0;return `<div class="subject-row"><div class="subject-meta"><strong>${esc(s)} · ${esc(t)}</strong><span>${cover}/${a.length} covered · ${m}% evidence estimate</span></div><div class="progress-track"><div class="progress-fill" style="width:${a.length?cover/a.length*100:0}%"></div></div></div>`}).join('')||'<p class="empty-hint">Add concepts to see topic reports.</p>'}
