function openConcept(c=null){const f=$('#conceptForm');f.reset();f.elements.id.value=c?.id||'';$('#conceptDialogTitle').textContent=c?'Edit concept':'Add concept';$('#deleteConcept').hidden=!c;const vals={subject:c?.subject||data.subjects[0],paper:c?.paper||'',topic:c?.topic||'',subtopic:c?.subtopic||'',name:c?.name||'',description:c?.description||'',type:c?.type||'mixed',difficulty:c?.difficulty||3,importance:c?.importance||3,learnMin:c?.learnMin||30,reviewMin:c?.reviewMin||15,practiceMin:c?.practiceMin||25,targetReps:c?.targetReps??data.settings.goals.repetitions,targetQuestions:c?.targetQuestions??data.settings.goals.questions,threshold:c?.threshold??data.settings.goals.mastery,prerequisites:(c?.prerequisites||[]).join(', '),notes:c?.notes||''};Object.entries(vals).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v});f.elements.inScope.checked=c?.inScope!==false;$('#conceptDialog').showModal()}
