function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported||!Array.isArray(imported.concepts)||!Array.isArray(imported.sessions))throw Error('This does not look like a StudyPilot backup.');if(!confirm('Merge imported data by record ID? Existing records with matching IDs will be updated; other records will be kept. Export a backup first if unsure.'))return;const merge=(old,inc)=>{const map=new Map(old.map(x=>[x.id,x]));inc.forEach(x=>map.set(x.id,x));return [...map.values()]};data={...data,...imported,profile:{...data.profile,...imported.profile},settings:{...data.settings,...imported.settings,goals:{...data.settings.goals,...imported.settings?.goals}},subjects:[...new Set([...data.subjects,...(imported.subjects||[])])],concepts:merge(data.concepts,imported.concepts),sessions:merge(data.sessions,imported.sessions||[]),tasks:merge(data.tasks,imported.tasks||[]),commitments:merge(data.commitments,imported.commitments||[]),exams:merge(data.exams,imported.exams||[]),availability:{...data.availability,...imported.availability},overrides:{...data.overrides,...imported.overrides}};save();renderAll();notify('Backup merged successfully. Existing records not present in the file were preserved.')}catch(e){notify(`Import failed safely: ${e.message}`,true)}};reader.readAsText(file)}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
