$('#conceptForm').addEventListener('submit',e=>{e.preventDefault();saveConcept(e.currentTarget)});$('#closeConcept').onclick=$('#cancelConcept').onclick=()=>$('#conceptDialog').close();$('#deleteConcept').onclick=deleteCurrentConcept;
